/**
 * Pure presentation helpers shared by the terminal reporters: colors, the
 * terminal width, durations, counters, and model-usage tallies. Stateless, so
 * the reporters own every decision about what to print and when.
 */
import picocolors from 'picocolors';
import type { ResultStatus } from '../run/records.ts';
import type { StepModelInfo, StepRecord } from '../run/steps.ts';
/** A picocolors instance; the reporter decides whether it emits color. */
export type Colors = ReturnType<typeof picocolors.createColors>;
/** Glyphs shared by the list reporter's permanent lines and its live tree. */
export declare const F_POINTER = "\u276F";
export declare const F_CHECK = "\u2713";
export declare const F_CROSS = "\u00D7";
/**
 * Sanitized and bounded: the one form untrusted text takes on the terminal.
 * Tabs become spaces, since a tab's width depends on the column it lands in
 * and would break the live window's row accounting.
 */
export declare function bounded(text: string): string;
/**
 * A failure for stderr, `CODE: message`: how the CLI prints what
 * stopped a command before its run, and how the runner prints a run error
 * when no list reporter shows it.
 */
export declare function failureLine(error: {
    readonly code: string;
    readonly message: string;
}): string;
/**
 * Clips to `max` code points with an ellipsis; untouched when it fits. For
 * text measured in characters (a markdown cell); a terminal row budget is
 * `fitColumns`.
 */
export declare function ellipsize(text: string, max: number): string;
/** The terminal width; a pty without a size reports 0, which counts as unknown. */
export declare function terminalColumns(): number;
/** The terminal height; a pty without a size reports 0, which counts as unknown. */
export declare function terminalRows(): number;
/** vitest's duration format: whole milliseconds under a second, two decimals above. */
export declare function formatTime(ms: number): string;
/** A span as `11m 23s`. Rounds to whole seconds first, so 119.5 s is `2m 0s` and never `1m 60s`. */
export declare function formatMinutes(ms: number): string;
/**
 * The summary's `Duration` cell: the seconds, then dimmed in parentheses the
 * same span in minutes once it has one and the startup split when a process
 * started (`64.89s (1m 5s, startup 86ms)`).
 */
export declare function durationText(pc: Colors, elapsedMs: number, startupMs: number): string;
/** Wall-clock `HH:MM:SS` for the summary's `Start at` row. */
export declare function formatClock(date: Date): string;
/** Compact token count: plain under a thousand, `12.4k`, then `4.2M`. */
export declare function formatTokens(count: number): string;
/** USD with enough precision for sub-cent model calls. */
export declare function formatCost(costUsd: number): string;
/** One padded summary title, right-aligned like vitest's `Test Files` column. */
export declare function padTitle(pc: Colors, title: string): string;
/**
 * The dashes of a full-width rule around `text`: centered, or with the text
 * pushed to the right edge as vitest draws `[1/3]` markers. Uncolored, so the
 * caller colors the dashes and the text independently.
 */
export declare function rule(text: string, align: 'center' | 'right'): {
    before: string;
    after: string;
};
export interface Counters {
    passed: number;
    failed: number;
    interrupted: number;
    flaky: number;
    skipped: number;
    total: number;
}
export declare function emptyCounters(): Counters;
/**
 * The counter a result status lands in. A timeout is a failure; an
 * interrupted test was stopped by the run, not by its own verdict, so it
 * counts on its own.
 */
export declare function statusBucket(status: ResultStatus): 'passed' | 'failed' | 'interrupted' | 'flaky' | 'skipped';
/** A result status, or a filter step's outcome, as a line of text says it: `timed out` for `timed-out`. */
export declare const STATUS_WORD: Record<ResultStatus, string>;
/** Counts results by bucket; `total` is the number of items. */
export declare function tally(items: readonly {
    readonly status: ResultStatus;
}[]): Counters;
/** A file's outcome from its tests: failed if any did, else interrupted if any was, skipped if all were, else passed. */
export declare function fileOutcome(counters: Counters): 'passed' | 'failed' | 'interrupted' | 'skipped';
/** `2 failed | 1 interrupted | 10 passed | 1 flaky (14)` in vitest's colors and order. */
export declare function stateString(pc: Colors, counters: Counters): string;
export interface AiUsage {
    calls: number;
    /** Input plus output tokens. */
    tokens: number;
    /** Input tokens alone; the denominator of the cached share. */
    inputTokens: number;
    /** Input tokens the provider served from its prompt cache; part of `inputTokens`. */
    cachedTokens: number;
    costUsd: number | undefined;
}
export declare function emptyUsage(): AiUsage;
export declare function addUsage(into: AiUsage, usage: AiUsage): void;
/** The model usage of several step lists summed. */
export declare function stepsUsage(stepLists: readonly (readonly StepRecord[])[]): AiUsage;
/** The model usage of several items summed. */
export declare function sumUsage(items: readonly {
    readonly usage: AiUsage;
}[]): AiUsage;
/**
 * Tokens, cached share, and cost, `12.4k tokens · 38% cached · $0.01`, or
 * undefined when no model was used. The cached share is the part of the input
 * the provider served from its prompt cache, and appears only when that part
 * is not empty.
 */
export declare function usageText(usage: AiUsage): string | undefined;
/**
 * How the trace cache handled a run's agent steps, by step: replayed whole
 * with no model turn, replayed in part before the model took over, or missed;
 * and the steps of passing tests whose recording was not saved.
 * A run with the cache off records no cache detail and tallies nothing.
 */
export interface CacheTally {
    replayed: number;
    handedOff: number;
    missed: number;
    notSaved: number;
}
/** The steps whose recording was not saved. */
export declare function notSavedCount(steps: readonly StepRecord[]): number;
export declare function emptyCacheTally(): CacheTally;
export declare function addCacheTally(into: CacheTally, counts: CacheTally): void;
/** The trace cache's part in several step lists, by step. */
export declare function stepsCacheTally(stepLists: readonly (readonly StepRecord[])[]): CacheTally;
/**
 * `9 replayed · 2 handed off · 4 missed · 1 not saved`, zero counts left
 * out, or undefined when no step went through the trace cache.
 */
export declare function cacheText(pc: Colors, counts: CacheTally): string | undefined;
/**
 * `provider/model`, the form the run header names the configured model in;
 * undefined when the record lacks either half, so a step an executor reported
 * without provenance never prints as `undefined/undefined`.
 */
export declare function stepModelLabel(model: Pick<StepModelInfo, 'provider' | 'model'>): string | undefined;
/** The models a run's steps reported, `provider/model` to the calls each answered. */
export type ModelTally = Map<string, number>;
export declare function addModelTally(into: ModelTally, counts: ModelTally): void;
/** The models several step lists reported, with their call counts. */
export declare function stepsModelTally(stepLists: readonly (readonly StepRecord[])[]): ModelTally;
/**
 * The models that answered, most calls first: one model by its label alone,
 * since the row's call total is its count, several as
 * `gateway/openai/gpt-6-luna-fast (22 calls) · typesafe-ai/jev (1 call)`;
 * undefined when no step reported a model.
 */
export declare function modelsText(counts: ModelTally): string | undefined;
/** `usageText` labeled `ai …` for lines where nothing else names it. */
export declare function aiSegment(usage: AiUsage): string | undefined;
/** The grapheme clusters of `text`, each with the columns it paints; ANSI sequences count as text, so strip them first. */
export declare function graphemes(text: string): {
    readonly text: string;
    readonly columns: number;
}[];
/** Printed width of a line in terminal columns, ANSI sequences excluded. */
export declare function visibleWidth(text: string): number;
/**
 * Clips terminal text to `columns` with the ellipsis inside the budget, whole
 * grapheme clusters only; untouched when it fits. Every budget derived from
 * the terminal width goes through this; `ellipsize` counts characters.
 */
export declare function fitColumns(text: string, columns: number): string;
/**
 * The title suffix of a `--repeat-each` run past the first: ` (repeat #2)`;
 * empty for the first run, and for a report written before results carried
 * `repeat`, which the renderers may still be handed.
 */
export declare function repeatSuffix(repeat: number | undefined): string;
/** A commit as the notices and the markdown page name it: its first seven characters. */
export declare function shortCommit(commit: string): string;
/**
 * What one test filter decided of the tests it was given: `kept 7 of 42
 * tests, left out 35`, `kept all 42 tests`, or `left out all 42 tests`. The
 * run's notice and the markdown page say it the same way.
 */
export declare function filterDecision(candidates: number, excluded: number): string;
